n// scripts/build-react.mjs at build time, so each deploy gets its own cache\n// and the old one is deleted on activate.\nconst CACHE='seat-desk-c4869a9be1eb';\nconst PRECACHE=[\"/index.html\",\"/assets/app-c4869a9be1eb.js\",\"/assets/app-c4869a9be1eb.css\"];\n\nself.addEventListener('install',event=>{\n  event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(PRECACHE)).then(()=>self.skipWaiting()));\n});\n\nself.addEventListener('activate',event=>{\n  event.waitUntil(\n    caches.keys()\n      .then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key))))\n      .then(()=>self.clients.claim())\n  );\n});\n\nself.addEventListener('fetch',event=>{\n  const request=event.request;\n  if(request.method!=='GET')return;\n  const url=new URL(request.url);\n  if(url.origin!==self.location.origin)return;\n  if(url.pathname.startsWith('/api/'))return; // live data: network only\n  if(request.mode==='navigate'){\n    // Shell: network first so updates arrive when online; the cached shell\n    // when offline. A fresh shell is saved for next time.\n    event.respondWith(\n      fetch(request).then(response=>{\n        // Only an HTML page may become the cached shell: a direct\n        // navigation to /sw.js or an asset returns JavaScript, and caching\n        // that as /index.html would break the next offline open.\n        if(response&&response.ok&&response.headers?.get?.('content-type')?.includes('text/html')){\n          const copy=response.clone();\n          caches.open(CACHE).then(cache=>cache.put('/index.html',copy)).catch(()=>{});\n        }\n        return response;\n      }).catch(()=>caches.match('/index.html'))\n    );\n    return;\n  }\n  if(url.pathname.startsWith('/assets/')){\n    // Hashed assets never change: cache first, fill the cache on a miss.\n    event.respondWith(\n      caches.match(request).then(hit=>{\n        if(hit)return hit;\n        return fetch(request).then(response=>{\n          if(response&&response.ok){\n            const copy=response.clone();\n            caches.open(CACHE).then(cache=>cache.put(request,copy)).catch(()=>{});\n          }\n          return response;\n        });\n      })\n    );\n  }\n});\n"};
export default {async fetch(request,env){try{const url=new URL(request.url),path=url.pathname;if(path.startsWith("/api/"))return await api(request,env);if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Method not allowed",{status:405});let canonical=path;try{canonical=decodeURIComponent(path).replace(/[\s\u200B\uFEFF]+$/g,"")||"/"}catch{}if(canonical!==decodeURI(path)){url.pathname=canonical;return Response.redirect(url.toString(),308)}const key=path in ASSETS?path:!path.startsWith("/assets/")&&!/\.[a-z0-9]+$/i.test(path)?"/index.html":null;if(!key)return new Response("Not found",{status:404,headers:{"Cache-Control":"no-store"}});const type=key.endsWith(".js")?"text/javascript":key.endsWith(".css")?"text/css":"text/html";return new Response(request.method==="HEAD"?null:ASSETS[key],{headers:{"Content-Type":type+"; charset=utf-8","Cache-Control":"no-store, max-age=0","CDN-Cache-Control":"no-store","X-Content-Type-Options":"nosniff","X-Seat-Desk-Build":"c4869a9be1eb"}})}catch{return json({error:"Service unavailable. Please retry."},503)}}};
